import java.util.Map;

public class Leaderboard {
    static int maxScore(Map<String, Integer> scores) {
        int best = Integer.MIN_VALUE;
        for (int s : scores.values()) {
            if (s > best) best = s;
        }
        return best;
    }

    public static String summary(Map<String, Integer> scores) {
        return "Top score: " + maxScore(scores) + " (" + scores.size() + " players)";
    }
}

