public class Test {
    public static void main(String[] a) {
        java.util.Map<String, Integer> m = java.util.Map.of("ann", 3, "bo", 9, "cy", -2);
        if (!(Leaderboard.maxScore(m) == 9)) throw new AssertionError("maxScore");
        if (!(Leaderboard.maxScore(java.util.Map.of("x", -5)) == -5)) throw new AssertionError("negative max");
        if (!(Leaderboard.summary(m).equals("Top score: 9 (3 players)"))) throw new AssertionError("summary unchanged");
        System.out.println("PASS");
    }
}
